SELECT CASE WHEN COUNT(1) > 0 THEN TRUE ELSE FALSE END
FROM guilds
WHERE name = #{name}

SELECT CASE WHEN COUNT(1) > 0 THEN TRUE ELSE FALSE END
FROM guilds
WHERE name = #{name}
  AND guild_id != #{guildId}

SELECT CASE WHEN COUNT(1) > 0 THEN TRUE ELSE FALSE END
FROM guilds
WHERE invite_code = #{inviteCode}

