mapper.select:
SELECT owner_user_id
FROM guilds
WHERE guild_id = #{guildId}

SELECT role
FROM guild_members
WHERE guild_id = #{guildId}
  AND user_id = #{userId}
  AND left_at IS NULL
LIMIT 1

SELECT CASE WHEN COUNT(1) > 0 THEN TRUE ELSE FALSE END
FROM guild_members
WHERE guild_id = #{guildId}
  AND user_id = #{userId}
  AND left_at IS NULL

mapper.update:
UPDATE guild_members
SET left_at = CURRENT_TIMESTAMP
WHERE guild_id = #{guildId}
  AND user_id = #{userId}
  AND left_at IS NULL

UPDATE guild_members
SET left_at = CURRENT_TIMESTAMP
WHERE guild_id = #{guildId}
  AND guild_member_id = #{memberId}
  AND left_at IS NULL

DELETE FROM guild_notices
WHERE guild_id = #{guildId}
  AND notice_id = #{noticeId}

mapper.select:
SELECT gjr.request_id, gjr.guild_id, g.name AS guild_name, g.invite_code, g.description AS guild_description, gjr.user_id, gjr.status, gjr.created_at, gjr.handled_at, handler.nickname AS handled_by_nickname FROM guild_join_requests gjr JOIN guilds g ON g.guild_id = gjr.guild_id LEFT JOIN users handler ON handler.user_id = gjr.handled_by WHERE gjr.user_id = #{userId}
AND gjr.status = #{status}
ORDER BY gjr.created_at DESC, gjr.request_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT gjr.request_id, gjr.guild_id, gjr.user_id, u.nickname, u.profile_image_url, c.character_id, c.name AS character_name, c.level AS character_level, gjr.status, gjr.created_at FROM guild_join_requests gjr JOIN users u ON u.user_id = gjr.user_id AND u.status = 'ACTIVE' LEFT JOIN characters c ON c.user_id = u.user_id WHERE gjr.guild_id = #{guildId}
AND gjr.status = #{status}
ORDER BY gjr.created_at DESC, gjr.request_id DESC LIMIT #{limit} OFFSET #{offset}
